from collections import Counter
def transform(g):
    cnt=Counter(v for row in g for v in row)
    rare={c for c,n in cnt.items() if n < 0.1*max(cnt.values())}
    fill=cnt.most_common(1)[0][0]
    lr=[i for i,row in enumerate(g) if any(v in rare for v in row)]
    lc=[j for j in range(len(g[0])) if any(g[i][j] in rare for i in range(len(g)))]
    L=[[g[r][c] for c in lc] for r in lr]
    nr,nc=len(lr)-1,len(lc)-1
    blocks=[[fill]*nc for _ in range(nr)]; pts=[]
    for r in range(nr):
        for c in range(nc):
            cs={L[r][c],L[r][c+1],L[r+1][c],L[r+1][c+1]}
            if len(cs)==1 and next(iter(cs)) in rare:
                blocks[r][c]=next(iter(cs)); pts.append((r,c))
    if not pts: return [[fill]]
    r0=min(p[0] for p in pts); r1=max(p[0] for p in pts); c0=min(p[1] for p in pts); c1=max(p[1] for p in pts)
    return [row[c0:c1+1] for row in blocks[r0:r1+1]]
